import{_ as r,a as t,b as l}from"./chunks/b4ba66242a96ee46f263.Bu5Xdql_.js";import{_ as o,C as i,o as s,c as n,j as e,a as h,E as d,a6 as c}from"./chunks/framework.CnPv4DE1.js";const x=JSON.parse('{"title":"如何在7天内重启你的人生","description":"","frontmatter":{"title":"如何在7天内重启你的人生","originalTitle":"How To Reset Your Life In 7 Days","date":"2024-01-05","originalUrl":"https://thedankoe.com/letters/how-to-reset-your-life-in-7-days/","minutes":10,"sourceHash":"8f33c6c95716b0ca017aec7add7ec34fddb6b151947fe6600629fafbbbb5be17","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/how-to-reset-your-life-in-7-days/"}]]},"headers":[],"relativePath":"letters/how-to-reset-your-life-in-7-days.md","filePath":"letters/how-to-reset-your-life-in-7-days.md"}'),u={name:"letters/how-to-reset-your-life-in-7-days.md"};function f(m,p,b,_,k,g){const a=i("ArticleMeta");return s(),n("div",null,[p[0]||(p[0]=e("h1",{id:"如何在7天内重启你的人生",tabindex:"-1"},[h("如何在7天内重启你的人生 "),e("a",{class:"header-anchor",href:"#如何在7天内重启你的人生","aria-label":'Permalink to "如何在7天内重启你的人生"'},"​")],-1)),d(a),p[1]||(p[1]=c('<p><a href="https://www.youtube.com/embed/wXcEtxlrPMA?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>两个月前，我在笔记里写下了这些。</p><p>我偶尔会给自己写信，以此作为一种觉察练习。</p><p>（为了让这篇通讯读起来更通顺，我做了一点编辑）：</p><blockquote><p>我再也找不到生活的乐趣了。</p><p>一切都不一样了。</p><p>还记得你以前经常一边长时间散步，一边阅读或者听讲座、有声书或播客的时候吗？那时你的脑海会被各种想法点亮。</p><p>你停不下笔。一切感觉都是那么无缝衔接。那段时期就像一阵旋风。长达6个月的心流状态。你打造了3个产品，获得了几百万读者，甚至还写了一本书。</p><p>如果现在让你从头再来一次，你还能做得这么好吗？</p><p>绝对不可能。</p><p>那时你每天是怎么过的？</p><p>我会起床，下楼去湖边散步，坐在池塘前的长椅上，看书并不停地做标记。</p><p>然后，我会回家洗个澡，走10分钟去咖啡馆，写上2个小时。每天早上的那2个小时，构筑了你现在生活的全部。</p><p>接着，我会再次回家，吃早饭（你那时在尝试不同的饮食法，也许这是个线索，因为实验带来了新鲜感和多巴胺），然后再出去散步。</p><p>刚过中午，我会去健身房，练完吃点东西，在YouTube上学点东西，然后再次出门散步。</p><p>你会和朋友聊聊天，也许再工作一会儿，看个剧，以此结束这一天。</p></blockquote><p>这事儿困扰我太久了。</p><p>我知道有办法找回那种更高的心智状态——不一定非要回到那种生活方式本身。</p><p>不过我不是一个爱抱怨的人（尽管那封写给自己的信听起来有些伤感），我喜欢在跟你们分享解决方案之前，先把自己的问题解决掉。</p><p>如果你跟我有点像，你就会注意到，人生中的这些低谷期是周期性的。</p><p>有那么几个月，你感觉自己站在世界之巅。你不断取得进步，停都停不下来。</p><p>然后，接下来的几个月节奏慢了下来。你感觉还不错，但事情已经不一样了。</p><p>最后，你碰壁了。你的愿景消耗殆尽。你感到迷茫。消极的想法开始淹没你的大脑——它们会蒙蔽你的心智，阻止你收集能让你对下一个人生目标产生疯狂痴迷的线索。</p><p>这封信是写给那些处于最后这个阶段的人的。</p><p>写给那些再也找不到昔日生活热情的人。</p><p>写给那些在读书或在大自然中漫步时再也找不到乐趣的人。</p><p>开始之前的2点说明：</p><ol><li>我的新书《专注的艺术》（The Art Of Focus）将于1月16日正式发售。你现在可以<a href="https://theartoffocusbook.com/" target="_blank" rel="noreferrer">预购Kindle或Audible版本</a>，或者等那天直接买平装本（在日历上记好日子）。</li><li><a href="https://university.kortex.co/" target="_blank" rel="noreferrer">Kortex University</a>——专为创作者经济打造的大学级体验——现已开放报名。90天开启你的数字职业生涯，把你的人生观、兴趣和专长转化为一份灵活的在线事业。</li></ol><h2 id="你的大脑是一台运行着-人生游戏-的超级计算机" tabindex="-1">你的大脑是一台运行着“人生游戏”的超级计算机 <a class="header-anchor" href="#你的大脑是一台运行着-人生游戏-的超级计算机" aria-label="Permalink to &quot;你的大脑是一台运行着“人生游戏”的超级计算机&quot;">​</a></h2><blockquote><p>当我们的大脑没有专注于存在或做事时，我们就会任由随机的想法进入我们的意识。这里的“随机”并不意味着一半好想法和一半坏想法。每产生一个好想法，就会有一百个坏想法。——《专注的艺术》</p></blockquote><p>我想让你把自己的大脑想象成一台超级计算机。</p><p>你处理信息的能力取决于几个因素，但我想让你关注你的RAM（运行内存）。</p><p>RAM——即“随机存取存储器”——是计算机最重要的部件之一，它决定了性能。</p><p>你运行的不同程序、打开的浏览器标签页，以及你所运行内容对性能的要求，消耗的RAM越多，你的运行速度就会越慢。</p><p>这和你的注意力，也就是你保留在意识中的关注点，没有什么不同。</p><p>人类每秒可以处理10到50比特的信息。算下来，你一生中处理的信息总量可达1250亿比特。</p><p>大多数人的生活状态是同时运行着多个高负荷的程序，这些程序正在耗尽他们有限的创造性能量。</p><ul><li>对过去所犯错误的悔恨想法</li><li>对未来充满压力的事件的担忧</li><li>为了逃避这些想法而产生的对食物和娱乐的渴望</li><li>渴望打破条件反射式生活方式的内心呐喊</li><li>一串优先级混乱且亟待完成的任务清单</li><li>那些本该完成却被遗忘了的任务所造成的未闭环状态</li></ul><p>这个单子还可以一直列下去。</p><p>现代人的心智默认会将注意力分散到无数个方向。我们在生活中压力重重，近乎病态。我们没有活在当下，没有带着无忧无虑的心境去专注未来的愿景，反而走向了反面。我们生活在由分散的注意力所虚构的现实中。</p><p>当我们在意识内容中容纳了太多关于过去或未来的东西时，混乱就会随之而来。心智倾向于无序。如果不加以控制，我们就会失去对生活的掌控感，而正是这种掌控感带来了乐趣。这种掌控感是通过控制意识来实现的。</p><p>单一的专注能带来清晰。碎片化的专注则会制造紧张感。紧张感会让压力趁虚而入。而压力，正是创造力的死敌。</p><h3 id="如何赢下-人生游戏" tabindex="-1">如何赢下“人生游戏” <a class="header-anchor" href="#如何赢下-人生游戏" aria-label="Permalink to &quot;如何赢下“人生游戏”&quot;">​</a></h3><p><img src="'+r+'" alt=""></p><p>让我们把你一生能处理的那1250亿比特信息想象成你的<em>人生潜能</em>。</p><p>现在，让我们把你的大脑看作是现实的消化系统。</p><p>如果你“吃下”太多的信息，你就会感到焦虑。</p><p>如果你“吃下”太少的信息，你就会感到无聊。</p><p>要将生活的乐趣最大化，就要最大化你停留在自身极限边缘的时间。</p><p>你能赢下这场人生游戏，靠的是在你尽可能多的体验中找到乐趣（enjoyment），而不是快感（pleasure）（这两者有很大的区别）。你的体验，就是当下的这一刻。</p><p>“赢下”人生游戏不是一个结果，而是一个过程。</p><p>要么，你现在就正在赢，无论你的情绪状态或在社会阶层中的地位如何；要么，你正在因为将心思投射到当下之外的地方而输掉游戏。</p><p>在健身健美中，促进肌肉生长的最佳营养摄入量，刚刚好超过维持现状的消耗量。如果你吃得太多，你会感到昏昏沉沉。如果你吃得太少，你又没有足够的能量去猛练。</p><p>在心智建设中，你必须将学习与构建同步进行。用日常的实践来消化你的体验。你之所以不知道下一步该走向何方，是因为你还没有接触到那些在未知中充当微弱光芒的信息。</p><p>在生活中，你必须涉足未知，以此为你的大脑提供燃料。</p><p>让自己暴露在新的信息和体验中（<strong>好奇心</strong>）。</p><p>利用那些信息去创造有价值的东西，以此来消化它（<strong>热情</strong>）。</p><p>通过实践，当这些体验成为你的一部分时，拓展你的心智（<strong>精通</strong>）。</p><p>通过将这种价值传递给他人，超越人生的那个阶段（<strong>连接</strong>）。</p><p><strong>这就是美好生活的秘方：</strong></p><p>通过追求那些将你引向未知的自发目标，利用你所获得的体验去创造、拓展并实现超越。</p><h3 id="创造你自己的游戏-或现实" tabindex="-1">创造你自己的游戏（或现实） <a class="header-anchor" href="#创造你自己的游戏-或现实" aria-label="Permalink to &quot;创造你自己的游戏（或现实）&quot;">​</a></h3><p>每个人都玩过让自己完全沉浸其中的游戏。</p><p>他们忘掉了一切，进入了心流状态，甚至可能没有意识到自己正处于巅峰体验中——这是一个美妙的境地，新的信息在现实穿过他们的身体时被消化吸收。</p><p>当你开始玩一款游戏时，你会经历一个新手教程阶段，它会向你介绍玩好这款游戏所需的规则、目标和技能。</p><p>游戏是一个目标层级体系：</p><ul><li>如何获胜</li><li>如何朝着获胜的每一个子目标推进</li><li>升级你的角色以继续推进</li></ul><p>游戏的每一关都需要一定级别的技能，去匹配那一关的挑战。</p><p>如果你是一个纯纯的新手，你根本没资格去挑战更高的关卡。你立刻就会输掉，而且很可能会直接放弃不玩了。</p><p>你必须像其他人一样，经历同样的成长过程。</p><p>你必须学习、失败、练习、变强，并在通关的过程中不断扩展你对这款游戏的认知。</p><p>在生活中，也是同样的道理。</p><p>所以，想要沉浸在你人生的游戏中，你首先必须创造它。</p><h2 id="如何在7天内重启你的人生-1" tabindex="-1">如何在7天内重启你的人生 <a class="header-anchor" href="#如何在7天内重启你的人生-1" aria-label="Permalink to &quot;如何在7天内重启你的人生&quot;">​</a></h2><p>当生活变得一团糟时，这就是我会经历的过程。</p><p>比如当你不断回想“过去生活更好”的那个时期。</p><p>或者当你的日常节奏崩溃，冒出各种琐碎的任务，耗尽你一天所有时间的时候。</p><p>我们将快速过一遍这个流程……请务必把它用起来。</p><p>以下就是你在7天内重启人生的方法：</p><h3 id="_1-记录你的感受" tabindex="-1">1) 记录你的感受 <a class="header-anchor" href="#_1-记录你的感受" aria-label="Permalink to &quot;1) 记录你的感受&quot;">​</a></h3><p>拿出一个笔记本，写下：</p><ul><li>你每天具体都在做些什么。</li><li>你在早上、下午和晚上的感受。</li></ul><p>花10分钟时间，写得具体一点。</p><p>这对于识别潜意识里的寄生虫（时间和精力的吸血鬼）非常重要。</p><p>我都是在<a href="https://thedankoe.com/planner" target="_blank" rel="noreferrer">The FOCI Planner</a>的季度部分完成所有这些记录的。</p><h3 id="_2-明确你想要什么" tabindex="-1">2) 明确你想要什么 <a class="header-anchor" href="#_2-明确你想要什么" aria-label="Permalink to &quot;2) 明确你想要什么&quot;">​</a></h3><p><img src="'+t+'" alt=""></p><p><em>你必须认识到你不想要什么，才能弄清楚你想要什么——哪怕那是破坏性的——去认识你到底不想要什么。不让自己犯错，才是最愚蠢的错误。</em></p><p>你不可能拥有绝对的确定性去知晓未来会发生什么。</p><p>这就是为什么大众会蜂拥向“安稳”的工作和信仰体系。</p><p>那只是一种为了逃避挣扎而产生的确定性幻觉。你无法跳过犯错的环节。错误就是你在黑暗中的明灯。</p><p>从一个最小可行性愿景（minimum viable vision）开始。</p><ul><li>你想让你的生活变成什么样？</li><li>你想让你的心智变成什么样？</li><li>你想让你的身材变成什么样？</li></ul><p><em>写得具体一点，写下你未来的每一个细节。</em></p><p>现在，把它拆解成一个个目标。</p><p>不是为了非得达成它，而是为了获得清晰感。</p><p>年度目标和月度目标。</p><p>你需要为人生找对方向。目标就是一个过滤器，帮你筛选该学什么技能、该抓住什么机会。</p><p>你的日常体验必须透过你的愿景来感知，把它看作是你想要赢下的那场游戏。</p><h3 id="_3-排序、剔除与重构你的一天" tabindex="-1">3) 排序、剔除与重构你的一天 <a class="header-anchor" href="#_3-排序、剔除与重构你的一天" aria-label="Permalink to &quot;3) 排序、剔除与重构你的一天&quot;">​</a></h3><p>你无法获得过去那种成果，原因在于：</p><ul><li>你觉得时间紧迫</li><li>你没有足够的精力去获得成果</li><li><em>你停止了做那些能产生结果的事情</em></li></ul><p>审视一下你在上面倾倒出的大脑思绪（brain dump）。</p><p>你能改变什么？</p><p>优先处理那些能产生结果的事情。</p><p>剔除那些偷偷溜进你一天当中（且根本不配出现在那里）的事情。</p><p>重构具体的任务和义务，以腾出更多的时间。</p><p>把你大脑里混乱的结构落实在纸面上，并重新组织它。</p><h3 id="_4-美好生活的基石习惯" tabindex="-1">4) 美好生活的基石习惯 <a class="header-anchor" href="#_4-美好生活的基石习惯" aria-label="Permalink to &quot;4) 美好生活的基石习惯&quot;">​</a></h3><p><img src="'+l+'" alt=""></p><p>你现在有了方向（目标），也清楚了为什么自己没能实现它们（反面目标）。</p><p>现在，你需要培养2个习惯来填补这个鸿沟：</p><ol><li><strong>学习</strong>——获取新奇的信息，为你掌握技能和积累知识提供燃料。</li><li><strong>构建</strong>——消化信息，打造心智肌肉。</li></ol><p>这两者都是昂贵的多巴胺。</p><p>从每天各做30分钟开始。</p><p>在早上进行30分钟的自我教育。</p><p>30分钟用来构建一个将有助于实现你愿景的项目。</p><p>如果你不能在每天早晨干扰最少的时候腾出1个小时来构建你的未来——那就回到第3步，把你的优先事项理清楚。</p><p>如果你愿意，你可以通过我的课程 <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 Hour Writer</a> 学习数字写作这项高价值技能，从而在新经济中构建未来。</p><h3 id="_5-制定一个为期一周的计划" tabindex="-1">5) 制定一个为期一周的计划 <a class="header-anchor" href="#_5-制定一个为期一周的计划" aria-label="Permalink to &quot;5) 制定一个为期一周的计划&quot;">​</a></h3><p>你生活之所以陷入这种混乱境地，是因为熵。</p><p>如果你不进行精神内务整理，你生活的秩序（进而也是你大脑的秩序）就会趋向无序。</p><p>这很危险，因为你可能会在这个过程中染上坏习惯。</p><p>习惯是很难打破的。</p><p>但凭借清晰的思路，你可以让这个过程变得更容易。</p><p>抽出10分钟时间。</p><p>写下你接下来一周要做的每一件事。</p><p>这听起来应该不会让人觉得疯狂或困难。</p><p>这就是你减少做出更好决策时产生的摩擦力的方法。</p><p>写下：</p><ul><li>你的晨间日常</li><li>你的专注工作日常</li><li>其他任务和会议</li><li>晚间日常</li></ul><p>最困难的部分，是当平庸的习惯受到威胁时，不去理会不可避免地冒出来的负面想法。在开启新计划时，正念是你的好朋友。</p><p>你必须在执行的过程中不断尝试。</p><p>如果日常安排无法让你进入心流，那就回到你的笔记本前，写下你第二天打算做些什么。</p><p>这就是你为自己的人生建立系统的方法。</p><p>你通过规划自己的一周、坚持计划、发现问题、尝试解决方案，并不断重复这个过程直到你触及理想的未来，以此来为你的生活建立一个系统。</p><p>如果你把这种“精神内务整理”变成一种常规习惯，随着时间的推移，它的效率会越来越高。</p><p>不知不觉中，新技能将成为你的第二天性，而你自己都会对你所走过的长路感到不可思议。</p><hr><p><a href="/en/letters/how-to-reset-your-life-in-7-days">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',129))])}const P=o(u,[["render",f]]);export{x as __pageData,P as default};
